#!/usr/bin/env node

/**
 * Task-local packager for the slack-api skill.
 *
 * Validates the skill (mirroring skill-creator's validate_skill.cjs rules) and
 * produces a distributable .skill zip using only Node built-ins (no external
 * zip binary). The output is verified by re-reading the archive.
 *
 * Usage: node package_slack_skill.cjs [skill-folder] [output-file]
 * Defaults: slack-api -> slack-api.skill (current directory)
 */

const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

// ---------- validation (mirrors skill-creator validate_skill.cjs) ----------

function getAllFiles(dir, fileList = []) {
  for (const entry of fs.readdirSync(dir)) {
    const full = path.join(dir, entry);
    if (fs.statSync(full).isDirectory()) {
      if (!['node_modules', '.git', '__pycache__'].includes(entry)) {
        getAllFiles(full, fileList);
      }
    } else {
      fileList.push(full);
    }
  }
  return fileList;
}

function validateSkill(skillPath) {
  if (!fs.existsSync(skillPath) || !fs.statSync(skillPath).isDirectory()) {
    return { valid: false, message: `Path is not a directory: ${skillPath}` };
  }
  const skillMdPath = path.join(skillPath, 'SKILL.md');
  if (!fs.existsSync(skillMdPath)) {
    return { valid: false, message: 'SKILL.md not found' };
  }
  const content = fs.readFileSync(skillMdPath, 'utf8');
  if (!content.startsWith('---')) {
    return { valid: false, message: 'No YAML frontmatter found' };
  }
  const parts = content.split('---');
  if (parts.length < 3) {
    return { valid: false, message: 'Invalid frontmatter format' };
  }
  const frontmatterText = parts[1];
  const nameMatch = frontmatterText.match(/^name:\s*(.+)$/m);
  const descMatch = frontmatterText.match(
    /^description:\s*(?:'([^']*)'|"([^"]*)"|(.+))$/m,
  );
  if (!nameMatch) return { valid: false, message: 'Missing "name" in frontmatter' };
  if (!descMatch) {
    return { valid: false, message: 'Description must be a single-line string: description: ...' };
  }
  const name = nameMatch[1].trim();
  const description = (
    descMatch[1] !== undefined ? descMatch[1] : descMatch[2] !== undefined ? descMatch[2] : descMatch[3] || ''
  ).trim();
  if (description.includes('\n')) {
    return { valid: false, message: 'Description must be a single line (no newlines)' };
  }
  if (!/^[a-z0-9-]+$/.test(name)) {
    return { valid: false, message: `Name "${name}" should be hyphen-case` };
  }
  if (description.length > 1024) {
    return { valid: false, message: 'Description is too long (max 1024)' };
  }
  for (const file of getAllFiles(skillPath)) {
    if (fs.readFileSync(file, 'utf8').includes('TODO:')) {
      return { valid: false, warning: `Found unresolved TODO in ${path.relative(skillPath, file)}` };
    }
  }
  return { valid: true, message: 'Skill is valid!' };
}

// ---------- minimal zip writer (pure Node) ----------

let CRC_TABLE = null;
function crc32(buf) {
  if (!CRC_TABLE) {
    CRC_TABLE = new Int32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      CRC_TABLE[n] = c;
    }
  }
  let crc = -1;
  for (let i = 0; i < buf.length; i++) crc = (crc >>> 8) ^ CRC_TABLE[(crc ^ buf[i]) & 0xff];
  return (crc ^ -1) >>> 0;
}

function dosDateTime(date) {
  const time = (date.getHours() << 11) | (date.getMinutes() << 5) | (date.getSeconds() >> 1);
  const day = ((date.getFullYear() - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate();
  return { time, day };
}

function buildZip(entries) {
  // entries: [{ name, data }] — names ending in '/' are directory entries
  const localChunks = [];
  const centralChunks = [];
  let offset = 0;
  const now = dosDateTime(new Date());

  for (const entry of entries) {
    const nameBuf = Buffer.from(entry.name, 'utf8');
    const isDir = entry.name.endsWith('/');
    const data = entry.data || Buffer.alloc(0);
    const method = isDir ? 0 : 8;
    const crc = isDir ? 0 : crc32(data);
    const compressed = method === 0 ? data : zlib.deflateRawSync(data);

    const lh = Buffer.alloc(30);
    lh.writeUInt32LE(0x04034b50, 0);
    lh.writeUInt16LE(20, 4); // version needed
    lh.writeUInt16LE(0, 6); // flags
    lh.writeUInt16LE(method, 8);
    lh.writeUInt16LE(now.time, 10);
    lh.writeUInt16LE(now.day, 12);
    lh.writeUInt32LE(crc, 14);
    lh.writeUInt32LE(compressed.length, 18);
    lh.writeUInt32LE(data.length, 22);
    lh.writeUInt16LE(nameBuf.length, 26);
    lh.writeUInt16LE(0, 28); // extra length
    localChunks.push(lh, nameBuf, compressed);

    const ch = Buffer.alloc(46);
    ch.writeUInt32LE(0x02014b50, 0);
    ch.writeUInt16LE(20, 4); // version made by
    ch.writeUInt16LE(20, 6); // version needed
    ch.writeUInt16LE(0, 8); // flags
    ch.writeUInt16LE(method, 10);
    ch.writeUInt16LE(now.time, 12);
    ch.writeUInt16LE(now.day, 14);
    ch.writeUInt32LE(crc, 16);
    ch.writeUInt32LE(compressed.length, 20);
    ch.writeUInt32LE(data.length, 24);
    ch.writeUInt16LE(nameBuf.length, 28);
    ch.writeUInt16LE(0, 30); // extra length
    ch.writeUInt16LE(0, 32); // comment length
    ch.writeUInt16LE(0, 34); // disk number
    ch.writeUInt16LE(0, 36); // internal attrs
    ch.writeUInt32LE(isDir ? 0x00100000 : 0, 38); // external attrs
    ch.writeUInt32LE(offset, 42); // local header offset
    centralChunks.push(ch, nameBuf);

    offset += lh.length + nameBuf.length + compressed.length;
  }

  const central = Buffer.concat(centralChunks);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(0, 4); // disk number
  eocd.writeUInt16LE(0, 6); // central dir disk
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(central.length, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20); // comment length

  return Buffer.concat([...localChunks, central, eocd]);
}

function verifyZip(filePath, expectedEntries) {
  const buf = fs.readFileSync(filePath);
  if (buf.length < 22 || buf.readUInt32LE(0) !== 0x04034b50) {
    throw new Error('output file is not a zip (bad local file header)');
  }
  let eocdOffset = -1;
  for (let i = buf.length - 22; i >= Math.max(0, buf.length - 65557); i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) {
      eocdOffset = i;
      break;
    }
  }
  if (eocdOffset === -1) throw new Error('output file is not a zip (EOCD not found)');
  const count = buf.readUInt16LE(eocdOffset + 10);
  if (count !== expectedEntries) {
    throw new Error(`zip entry count mismatch: expected ${expectedEntries}, found ${count}`);
  }
  return count;
}

// ---------- main ----------

function main() {
  const skillPath = path.resolve(process.argv[2] || 'slack-api');
  const outFile = path.resolve(process.argv[3] || 'slack-api.skill');

  console.log('Validating skill...');
  const result = validateSkill(skillPath);
  if (result.warning) {
    console.error(`Failure: ${result.warning}`);
    process.exit(1);
  }
  if (!result.valid) {
    console.error(`Failure: ${result.message}`);
    process.exit(1);
  }
  console.log(`OK: ${result.message}`);

  const files = getAllFiles(skillPath).sort();
  const entries = [];
  const rel = (p) => path.relative(skillPath, p).split(path.sep).join('/');

  const dirs = new Set();
  for (const f of files) {
    let d = path.dirname(path.relative(skillPath, f));
    while (d !== '.') {
      dirs.add(d.split(path.sep).join('/'));
      d = path.dirname(d);
    }
  }
  for (const d of [...dirs].sort()) {
    entries.push({ name: `${d}/`, data: Buffer.alloc(0) });
  }
  for (const f of files) {
    entries.push({ name: rel(f), data: fs.readFileSync(f) });
  }

  const zipBuf = buildZip(entries);
  fs.writeFileSync(outFile, zipBuf);
  const count = verifyZip(outFile, entries.length);

  console.log(`OK: packaged slack-api.skill with ${count} entries (${zipBuf.length} bytes):`);
  for (const e of entries) console.log(`  ${e.name}`);
  console.log(`Done: ${outFile}`);
}

main();

/* eslint-env node */

/**
 * Quick validation logic for skills.
 * Leveraging existing dependencies when possible or providing a zero-dep fallback.
 */

const fs = require('node:fs');
const path = require('node:path');

function validateSkill(skillPath) {
  if (!fs.existsSync(skillPath) || !fs.statSync(skillPath).isDirectory()) {
    return { valid: false, message: `Path is not a directory: ${skillPath}` };
  }

  const skillMdPath = path.join(skillPath, 'SKILL.md');
  if (!fs.existsSync(skillMdPath)) {
    return { valid: false, message: 'SKILL.md not found' };
  }

  const content = fs.readFileSync(skillMdPath, 'utf8');
  if (!content.startsWith('---')) {
    return { valid: false, message: 'No YAML frontmatter found' };
  }

  const parts = content.split('---');
  if (parts.length < 3) {
    return { valid: false, message: 'Invalid frontmatter format' };
  }

  const frontmatterText = parts[1];

  const nameMatch = frontmatterText.match(/^name:\s*(.+)$/m);
  // Match description: "text" or description: 'text' or description: text
  const descMatch = frontmatterText.match(
    /^description:\s*(?:'([^']*)'|"([^"]*)"|(.+))$/m,
  );

  if (!nameMatch)
    return { valid: false, message: 'Missing "name" in frontmatter' };
  if (!descMatch)
    return {
      valid: false,
      message: 'Description must be a single-line string: description: ...',
    };

  const name = nameMatch[1].trim();
  const description = (
    descMatch[1] !== undefined
      ? descMatch[1]
      : descMatch[2] !== undefined
        ? descMatch[2]
        : descMatch[3] || ''
  ).trim();

  if (description.includes('\n')) {
    return {
      valid: false,
      message: 'Description must be a single line (no newlines)',
    };
  }

  if (!/^[a-z0-9-]+$/.test(name)) {
    return { valid: false, message: `Name "${name}" should be hyphen-case` };
  }

  if (description.length > 1024) {
    return { valid: false, message: 'Description is too long (max 1024)' };
  }

  // Check for TODOs
  const files = getAllFiles(skillPath);
  for (const file of files) {
    const fileContent = fs.readFileSync(file, 'utf8');
    if (fileContent.includes('TODO:')) {
      return {
        valid: true,
        message: 'Skill has unresolved TODOs',
        warning: `Found unresolved TODO in ${path.relative(skillPath, file)}`,
      };
    }
  }

  return { valid: true, message: 'Skill is valid!' };
}

function getAllFiles(dir, fileList = []) {
  const files = fs.readdirSync(dir);
  files.forEach((file) => {
    const name = path.join(dir, file);
    if (fs.statSync(name).isDirectory()) {
      if (!['node_modules', '.git', '__pycache__'].includes(file)) {
        getAllFiles(name, fileList);
      }
    } else {
      fileList.push(name);
    }
  });
  return fileList;
}

if (require.main === module) {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    console.log('Usage: node validate_skill.js <skill_directory>');
    process.exit(1);
  }

  const skillDirArg = args[0];
  if (skillDirArg.includes('..')) {
    console.error('❌ Error: Path traversal detected in skill directory path.');
    process.exit(1);
  }

  const result = validateSkill(path.resolve(skillDirArg));
  if (result.warning) {
    console.warn(`⚠️  ${result.warning}`);
  }
  if (result.valid) {
    console.log(`✅ ${result.message}`);
  } else {
    console.error(`❌ ${result.message}`);
    process.exit(1);
  }
}

module.exports = { validateSkill };

