#!/usr/bin/env node

/**
 * slack_api.cjs — CLI wrapper around the Slack Web API.
 *
 * Usage: node slack_api.cjs <command> [--key value ...]
 *
 * Auth: SLACK_TOKEN env var or --token <token> (bot or user token).
 *
 * Output: single-line Success:/Failure: messages, truncated for agent context.
 * Exit codes: 0 success, 1 failure.
 *
 * Requires Node.js 18+ (global fetch).
 */

const API_BASE = 'https://slack.com/api/';

const COMMANDS = {
  post: {
    endpoint: 'chat.postMessage',
    required: ['channel'],
    optional: ['text', 'thread_ts', 'blocks', 'username', 'icon_emoji', 'link_names', 'unfurl_links', 'unfurl_media'],
  },
  update: {
    endpoint: 'chat.update',
    required: ['channel', 'ts'],
    optional: ['text', 'blocks', 'link_names'],
  },
  delete: {
    endpoint: 'chat.delete',
    required: ['channel', 'ts'],
    optional: [],
  },
  'list-channels': {
    endpoint: 'conversations.list',
    required: [],
    optional: ['limit', 'cursor', 'types', 'exclude_archived', 'team_id'],
  },
  history: {
    endpoint: 'conversations.history',
    required: ['channel'],
    optional: ['limit', 'oldest', 'latest', 'inclusive'],
  },
  'create-channel': {
    endpoint: 'conversations.create',
    required: ['name'],
    optional: ['is_private', 'team_id'],
  },
  invite: {
    endpoint: 'conversations.invite',
    required: ['channel', 'users'],
    optional: [],
  },
  users: {
    endpoint: 'users.list',
    required: [],
    optional: ['limit', 'cursor', 'team_id', 'include_locale'],
  },
  'user-by-email': {
    endpoint: 'users.lookupByEmail',
    required: ['email'],
    optional: [],
  },
};

const USAGE = `Slack API CLI

Usage:
  node slack_api.cjs <command> [--key value ...]

Authentication:
  SLACK_TOKEN env var or --token <token> (bot or user token)

Commands:
  post            Post a message.       --channel <id|name> --text <text>
                                        [--thread-ts <ts>] [--blocks <json>]
                                        [--username <name>] [--link_names]
  update          Update a message.     --channel <id> --ts <ts> --text <text>
  delete          Delete a message.     --channel <id> --ts <ts>
  list-channels   List channels.        [--limit <n>] [--cursor <c>]
                                        [--types public_channel,private_channel]
  history         Read channel history. --channel <id> [--limit <n>]
                                        [--oldest <unix>] [--latest <unix>]
  create-channel  Create a channel.     --name <name> [--private]
  invite          Invite users.         --channel <id> --users <U1,U2,...>
  users           List workspace users. [--limit <n>] [--cursor <c>]
  user-by-email   Find user by email.   --email <addr>

Exit codes: 0 success, 1 failure.`;

function fail(message) {
  process.stderr.write(`Failure: ${message}\n`);
  process.exit(1);
}

function truncate(str, max) {
  const s = String(str == null ? '' : str);
  if (s.length <= max) return s;
  return `${s.slice(0, max - 1)}…`;
}

function parseArgs(argv) {
  const opts = {};
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--help' || arg === '-h') {
      opts.help = true;
      continue;
    }
    if (arg.startsWith('--')) {
      let key = arg.slice(2);
      let value;
      const eq = key.indexOf('=');
      if (eq !== -1) {
        value = key.slice(eq + 1);
        key = key.slice(0, eq);
      }
      if (value === undefined) {
        const next = argv[i + 1];
        if (next !== undefined && !next.startsWith('--')) {
          value = next;
          i++;
        } else {
          value = 'true';
        }
      }
      opts[key] = value;
    } else {
      positional.push(arg);
    }
  }
  return { opts, positional };
}

async function main() {
  const { opts, positional } = parseArgs(process.argv.slice(2));

  if (opts.help || positional.length === 0) {
    process.stdout.write(`${USAGE}\n`);
    process.exit(opts.help ? 0 : 1);
  }

  const command = positional[0];
  const spec = COMMANDS[command];
  if (!spec) {
    fail(`Unknown command "${command}". Run with --help for usage.`);
  }

  const token = opts.token || process.env.SLACK_TOKEN;
  if (!token) {
    fail('SLACK_TOKEN is not set. Export SLACK_TOKEN or pass --token <token>.');
  }

  // --private is an alias for --is_private
  if (opts.private !== undefined && opts.is_private === undefined) {
    opts.is_private = opts.private;
  }

  const allowed = new Set([...spec.required, ...spec.optional, 'token', 'help', 'private']);
  for (const key of Object.keys(opts)) {
    if (!allowed.has(key)) {
      fail(`Unknown option "--${key}" for "${command}". Allowed: ${[...allowed].join(', ')}`);
    }
  }

  for (const req of spec.required) {
    const value = opts[req];
    if (value === undefined || value === 'true') {
      fail(`Missing required option --${req} for "${command}".`);
    }
  }

  if ((command === 'post' || command === 'update') && opts.text === undefined && opts.blocks === undefined) {
    fail(`"${command}" requires --text or --blocks.`);
  }

  if (opts.limit !== undefined && !/^\d+$/.test(opts.limit)) {
    fail(`--limit must be an integer, got "${opts.limit}".`);
  }

  const payload = {};
  for (const key of [...spec.required, ...spec.optional]) {
    if (opts[key] !== undefined) payload[key] = opts[key];
  }

  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(payload)) {
    params.append(key, String(value));
  }

  let res;
  try {
    res = await fetch(`${API_BASE}${spec.endpoint}`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: params.toString(),
      signal: AbortSignal.timeout(30000),
    });
  } catch (err) {
    fail(`Network error calling ${spec.endpoint}: ${err.message}`);
  }

  let json;
  try {
    json = await res.json();
  } catch {
    fail(`Invalid JSON response (HTTP ${res.status}) from ${spec.endpoint}.`);
  }

  if (!json.ok) {
    const detail =
      json.response_metadata && json.response_metadata.messages
        ? ` (${json.response_metadata.messages.join('; ')})`
        : '';
    const retryAfter = res.headers.get('retry-after');
    const retryNote = retryAfter ? ` (Retry-After: ${retryAfter}s)` : '';
    fail(`Slack API error: ${json.error}${detail}${retryNote}`);
  }

  switch (command) {
    case 'post': {
      const text = (json.message && json.message.text) || payload.text || '';
      process.stdout.write(
        `Success: Message posted to ${json.channel} (ts=${json.ts}). text="${truncate(text, 200)}"\n`,
      );
      break;
    }
    case 'update': {
      const text = (json.message && json.message.text) || payload.text || '';
      process.stdout.write(
        `Success: Message updated in ${json.channel} (ts=${json.ts}). text="${truncate(text, 200)}"\n`,
      );
      break;
    }
    case 'delete':
      process.stdout.write(
        `Success: Message deleted (channel=${json.channel}, ts=${json.ts}).\n`,
      );
      break;
    case 'list-channels': {
      const channels = json.channels || [];
      const lines = channels
        .slice(0, 50)
        .map(
          (c) =>
            `${c.id} | ${c.name} | ${c.is_private ? 'private' : 'public'} | members=${c.num_members ?? '?'}`,
        );
      process.stdout.write(`Success: ${channels.length} channel(s).\n${lines.join('\n')}\n`);
      if (json.response_metadata && json.response_metadata.next_cursor) {
        process.stdout.write(`next_cursor=${json.response_metadata.next_cursor}\n`);
      }
      break;
    }
    case 'history': {
      const msgs = json.messages || [];
      const lines = msgs
        .slice(0, 50)
        .map(
          (m) =>
            `${m.ts} | user=${m.user || m.bot_id || '?'} | ${truncate(m.text || '(no text)', 200)}`,
        );
      process.stdout.write(`Success: ${msgs.length} message(s) in ${payload.channel}.\n${lines.join('\n')}\n`);
      if (json.response_metadata && json.response_metadata.next_cursor) {
        process.stdout.write(`next_cursor=${json.response_metadata.next_cursor}\n`);
      }
      break;
    }
    case 'create-channel':
      process.stdout.write(
        `Success: ${json.is_private ? 'Private' : 'Public'} channel created: ${json.channel.name} (id=${json.channel.id}).\n`,
      );
      break;
    case 'invite':
      process.stdout.write(
        `Success: Invited ${payload.users} to channel ${json.channel ? json.channel.id : payload.channel}.\n`,
      );
      break;
    case 'users': {
      const users = json.members || [];
      const lines = users
        .slice(0, 50)
        .map((u) => `${u.id} | ${u.name} | ${u.real_name || ''} | ${u.deleted ? 'deleted' : 'active'}`);
      process.stdout.write(`Success: ${users.length} user(s).\n${lines.join('\n')}\n`);
      if (json.response_metadata && json.response_metadata.next_cursor) {
        process.stdout.write(`next_cursor=${json.response_metadata.next_cursor}\n`);
      }
      break;
    }
    case 'user-by-email': {
      const u = json.user || {};
      process.stdout.write(
        `Success: ${u.name} (id=${u.id}, real_name=${u.real_name || ''}, tz=${u.tz || ''}).\n`,
      );
      break;
    }
  }
}

main();

#!/usr/bin/env node

/**
 * Task-local packaging tool for the slack-api skill.
 *
 * Mirrors the skill-creator's validation rules and produces the distributable
 * .skill archive (a zip) in pure Node, so no system `zip` binary is needed.
 *
 * The archive contains only the skill files (SKILL.md, scripts/, references/);
 * this tooling file and other dotfiles are excluded.
 *
 * Usage: node .package.cjs
 * Output: <parent>/slack-api.skill
 */

const fs = require('node:fs');
const path = require('node:path');

const SKILL_DIR = __dirname;
const SKILL_NAME = path.basename(SKILL_DIR);
const ZIP_NAME = `${SKILL_NAME}.skill`;
const OUTPUT_PATH = path.resolve(SKILL_DIR, '..', ZIP_NAME);

function fail(message) {
  process.stderr.write(`Failure: ${message}\n`);
  process.exit(1);
}

// ---- Validation (mirrors skill-creator's validate_skill.cjs) ----

function allTextFiles(dir) {
  const out = [];
  for (const name of fs.readdirSync(dir)) {
    if (name.startsWith('.')) continue; // skip tooling/dotfiles
    const full = path.join(dir, name);
    if (fs.statSync(full).isDirectory()) out.push(...allTextFiles(full));
    else out.push(full);
  }
  return out;
}

function validateSkill(skillPath) {
  const skillMdPath = path.join(skillPath, 'SKILL.md');
  if (!fs.existsSync(skillMdPath)) return 'SKILL.md not found';
  const content = fs.readFileSync(skillMdPath, 'utf8');
  if (!content.startsWith('---')) return 'No YAML frontmatter found';
  const parts = content.split('---');
  if (parts.length < 3) return 'Invalid frontmatter format';
  const fm = parts[1];

  const nameMatch = fm.match(/^name:\s*(.+)$/m);
  const descMatch = fm.match(/^description:\s*(?:'([^']*)'|"([^"]*)"|(.+))$/m);
  if (!nameMatch) return 'Missing "name" in frontmatter';
  if (!descMatch) return 'Description must be a single-line string: description: ...';

  const name = nameMatch[1].trim();
  const description = (descMatch[1] !== undefined ? descMatch[1] : descMatch[2] !== undefined ? descMatch[2] : descMatch[3] || '').trim();
  if (description.includes('\n')) return 'Description must be a single line (no newlines)';
  if (!/^[a-z0-9-]+$/.test(name)) return `Name "${name}" should be hyphen-case`;
  if (description.length > 1024) return 'Description is too long (max 1024)';
  if (name !== path.basename(skillPath)) {
    return `Frontmatter name "${name}" does not match folder "${path.basename(skillPath)}"`;
  }

  for (const file of allTextFiles(skillPath)) {
    const text = fs.readFileSync(file, 'utf8');
    if (text.includes('TODO:')) {
      return `Unresolved TODO marker in ${path.relative(skillPath, file)}`;
    }
  }
  return null;
}

// ---- ZIP writer (STORE method, no compression, pure Node) ----

const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32(buf) {
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc = CRC_TABLE[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function dosDateTime(date) {
  const time = (date.getHours() << 11) | (date.getMinutes() << 5) | (date.getSeconds() >> 1);
  const dosDate = ((date.getFullYear() - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate();
  return { time, date: dosDate };
}

function collectEntries(dir, base = '') {
  const entries = [];
  for (const name of fs.readdirSync(dir).sort()) {
    if (name.startsWith('.') || name === ZIP_NAME) continue;
    const full = path.join(dir, name);
    const rel = base ? `${base}/${name}` : name;
    if (fs.statSync(full).isDirectory()) entries.push(...collectEntries(full, rel));
    else entries.push({ name: rel, full });
  }
  return entries;
}

function buildZip(entries) {
  const chunks = [];
  const central = [];
  let offset = 0;

  for (const e of entries) {
    const data = fs.readFileSync(e.full);
    const nameBuf = Buffer.from(e.name, 'utf8');
    const crc = crc32(data);
    const { time, date } = dosDateTime(fs.statSync(e.full).mtime);

    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(0, 6);
    local.writeUInt16LE(0, 8);
    local.writeUInt16LE(time, 10);
    local.writeUInt16LE(date, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(data.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(nameBuf.length, 26);
    local.writeUInt16LE(0, 28);
    chunks.push(local, nameBuf, data);

    const cen = Buffer.alloc(46);
    cen.writeUInt32LE(0x02014b50, 0);
    cen.writeUInt16LE(20, 4);
    cen.writeUInt16LE(20, 6);
    cen.writeUInt16LE(0, 8);
    cen.writeUInt16LE(0, 10);
    cen.writeUInt16LE(time, 12);
    cen.writeUInt16LE(date, 14);
    cen.writeUInt32LE(crc, 16);
    cen.writeUInt32LE(data.length, 20);
    cen.writeUInt32LE(data.length, 24);
    cen.writeUInt16LE(nameBuf.length, 28);
    cen.writeUInt16LE(0, 30);
    cen.writeUInt16LE(0, 32);
    cen.writeUInt16LE(0, 34);
    cen.writeUInt16LE(0, 36);
    cen.writeUInt32LE(0, 38);
    cen.writeUInt32LE(offset, 42);
    central.push(cen, nameBuf);

    offset += local.length + nameBuf.length + data.length;
  }

  const cdSize = central.reduce((s, c) => s + c.length, 0);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(0, 4);
  eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(cdSize, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);

  return Buffer.concat([...chunks, ...central, eocd]);
}

function verifyZip(buf, expectedEntries) {
  if (buf.length < 22) return 'archive too short';
  const eocdOffset = buf.length - 22;
  if (buf.readUInt32LE(eocdOffset) !== 0x06054b50) return 'missing end-of-central-directory record';
  const count = buf.readUInt16LE(eocdOffset + 10);
  if (count !== expectedEntries.length) {
    return `entry count mismatch: ${count} != ${expectedEntries.length}`;
  }
  let off = buf.readUInt32LE(eocdOffset + 16);
  for (const e of expectedEntries) {
    if (buf.readUInt32LE(off) !== 0x02014b50) return 'bad central directory signature';
    const nameLen = buf.readUInt16LE(off + 28);
    const name = buf.toString('utf8', off + 46, off + 46 + nameLen);
    if (name !== e.name) return `central directory name mismatch: ${name}`;
    const crc = buf.readUInt32LE(off + 16);
    const size = buf.readUInt32LE(off + 24);
    const localOff = buf.readUInt32LE(off + 42);
    if (buf.readUInt32LE(localOff) !== 0x04034b50) return `bad local header signature for ${name}`;
    const nameLenLocal = buf.readUInt16LE(localOff + 26);
    const dataStart = localOff + 30 + nameLenLocal;
    const data = buf.subarray(dataStart, dataStart + size);
    if (crc32(data) !== crc) return `CRC mismatch for ${name}`;
    off += 46 + nameLen;
  }
  return null;
}

// ---- Main ----

const validationError = validateSkill(SKILL_DIR);
if (validationError) fail(`Validation failed: ${validationError}`);

const entries = collectEntries(SKILL_DIR);
if (entries.length === 0) fail('No skill files found to package.');

const zip = buildZip(entries);
fs.writeFileSync(OUTPUT_PATH, zip);

const verifyError = verifyZip(zip, entries);
if (verifyError) fail(`Self-check failed: ${verifyError}`);

process.stdout.write(
  `Success: Validated and packaged ${entries.length} file(s) into ${OUTPUT_PATH} (${zip.length} bytes): ${entries.map((e) => e.name).join(', ')}\n`,
);

