#!/usr/bin/env node

/**
 * slack_api.cjs — CLI wrapper around the Slack Web API.
 *
 * Usage: node slack_api.cjs <command> [--key value ...]
 *
 * Auth: SLACK_TOKEN env var or --token <token> (bot or user token).
 *
 * Output: single-line Success:/Failure: messages, truncated for agent context.
 * Exit codes: 0 success, 1 failure.
 *
 * Requires Node.js 18+ (global fetch).
 */

const API_BASE = 'https://slack.com/api/';

const COMMANDS = {
  post: {
    endpoint: 'chat.postMessage',
    required: ['channel'],
    optional: ['text', 'thread_ts', 'blocks', 'username', 'icon_emoji', 'link_names', 'unfurl_links', 'unfurl_media'],
  },
  update: {
    endpoint: 'chat.update',
    required: ['channel', 'ts'],
    optional: ['text', 'blocks', 'link_names'],
  },
  delete: {
    endpoint: 'chat.delete',
    required: ['channel', 'ts'],
    optional: [],
  },
  'list-channels': {
    endpoint: 'conversations.list',
    required: [],
    optional: ['limit', 'cursor', 'types', 'exclude_archived', 'team_id'],
  },
  history: {
    endpoint: 'conversations.history',
    required: ['channel'],
    optional: ['limit', 'oldest', 'latest', 'inclusive'],
  },
  'create-channel': {
    endpoint: 'conversations.create',
    required: ['name'],
    optional: ['is_private', 'team_id'],
  },
  invite: {
    endpoint: 'conversations.invite',
    required: ['channel', 'users'],
    optional: [],
  },
  users: {
    endpoint: 'users.list',
    required: [],
    optional: ['limit', 'cursor', 'team_id', 'include_locale'],
  },
  'user-by-email': {
    endpoint: 'users.lookupByEmail',
    required: ['email'],
    optional: [],
  },
};

const USAGE = `Slack API CLI

Usage:
  node slack_api.cjs <command> [--key value ...]

Authentication:
  SLACK_TOKEN env var or --token <token> (bot or user token)

Commands:
  post            Post a message.       --channel <id|name> --text <text>
                                        [--thread-ts <ts>] [--blocks <json>]
                                        [--username <name>] [--link_names]
  update          Update a message.     --channel <id> --ts <ts> --text <text>
  delete          Delete a message.     --channel <id> --ts <ts>
  list-channels   List channels.        [--limit <n>] [--cursor <c>]
                                        [--types public_channel,private_channel]
  history         Read channel history. --channel <id> [--limit <n>]
                                        [--oldest <unix>] [--latest <unix>]
  create-channel  Create a channel.     --name <name> [--private]
  invite          Invite users.         --channel <id> --users <U1,U2,...>
  users           List workspace users. [--limit <n>] [--cursor <c>]
  user-by-email   Find user by email.   --email <addr>

Exit codes: 0 success, 1 failure.`;

function fail(message) {
  process.stderr.write(`Failure: ${message}\n`);
  process.exit(1);
}

function truncate(str, max) {
  const s = String(str == null ? '' : str);
  if (s.length <= max) return s;
  return `${s.slice(0, max - 1)}…`;
}

function parseArgs(argv) {
  const opts = {};
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--help' || arg === '-h') {
      opts.help = true;
      continue;
    }
    if (arg.startsWith('--')) {
      let key = arg.slice(2);
      let value;
      const eq = key.indexOf('=');
      if (eq !== -1) {
        value = key.slice(eq + 1);
        key = key.slice(0, eq);
      }
      if (value === undefined) {
        const next = argv[i + 1];
        if (next !== undefined && !next.startsWith('--')) {
          value = next;
          i++;
        } else {
          value = 'true';
        }
      }
      opts[key] = value;
    } else {
      positional.push(arg);
    }
  }
  return { opts, positional };
}

async function main() {
  const { opts, positional } = parseArgs(process.argv.slice(2));

  if (opts.help || positional.length === 0) {
    process.stdout.write(`${USAGE}\n`);
    process.exit(opts.help ? 0 : 1);
  }

  const command = positional[0];
  const spec = COMMANDS[command];
  if (!spec) {
    fail(`Unknown command "${command}". Run with --help for usage.`);
  }

  const token = opts.token || process.env.SLACK_TOKEN;
  if (!token) {
    fail('SLACK_TOKEN is not set. Export SLACK_TOKEN or pass --token <token>.');
  }

  // --private is an alias for --is_private
  if (opts.private !== undefined && opts.is_private === undefined) {
    opts.is_private = opts.private;
  }

  const allowed = new Set([...spec.required, ...spec.optional, 'token', 'help', 'private']);
  for (const key of Object.keys(opts)) {
    if (!allowed.has(key)) {
      fail(`Unknown option "--${key}" for "${command}". Allowed: ${[...allowed].join(', ')}`);
    }
  }

  for (const req of spec.required) {
    const value = opts[req];
    if (value === undefined || value === 'true') {
      fail(`Missing required option --${req} for "${command}".`);
    }
  }

  if ((command === 'post' || command === 'update') && opts.text === undefined && opts.blocks === undefined) {
    fail(`"${command}" requires --text or --blocks.`);
  }

  if (opts.limit !== undefined && !/^\d+$/.test(opts.limit)) {
    fail(`--limit must be an integer, got "${opts.limit}".`);
  }

  const payload = {};
  for (const key of [...spec.required, ...spec.optional]) {
    if (opts[key] !== undefined) payload[key] = opts[key];
  }

  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(payload)) {
    params.append(key, String(value));
  }

  let res;
  try {
    res = await fetch(`${API_BASE}${spec.endpoint}`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: params.toString(),
      signal: AbortSignal.timeout(30000),
    });
  } catch (err) {
    fail(`Network error calling ${spec.endpoint}: ${err.message}`);
  }

  let json;
  try {
    json = await res.json();
  } catch {
    fail(`Invalid JSON response (HTTP ${res.status}) from ${spec.endpoint}.`);
  }

  if (!json.ok) {
    const detail =
      json.response_metadata && json.response_metadata.messages
        ? ` (${json.response_metadata.messages.join('; ')})`
        : '';
    const retryAfter = res.headers.get('retry-after');
    const retryNote = retryAfter ? ` (Retry-After: ${retryAfter}s)` : '';
    fail(`Slack API error: ${json.error}${detail}${retryNote}`);
  }

  switch (command) {
    case 'post': {
      const text = (json.message && json.message.text) || payload.text || '';
      process.stdout.write(
        `Success: Message posted to ${json.channel} (ts=${json.ts}). text="${truncate(text, 200)}"\n`,
      );
      break;
    }
    case 'update': {
      const text = (json.message && json.message.text) || payload.text || '';
      process.stdout.write(
        `Success: Message updated in ${json.channel} (ts=${json.ts}). text="${truncate(text, 200)}"\n`,
      );
      break;
    }
    case 'delete':
      process.stdout.write(
        `Success: Message deleted (channel=${json.channel}, ts=${json.ts}).\n`,
      );
      break;
    case 'list-channels': {
      const channels = json.channels || [];
      const lines = channels
        .slice(0, 50)
        .map(
          (c) =>
            `${c.id} | ${c.name} | ${c.is_private ? 'private' : 'public'} | members=${c.num_members ?? '?'}`,
        );
      process.stdout.write(`Success: ${channels.length} channel(s).\n${lines.join('\n')}\n`);
      if (json.response_metadata && json.response_metadata.next_cursor) {
        process.stdout.write(`next_cursor=${json.response_metadata.next_cursor}\n`);
      }
      break;
    }
    case 'history': {
      const msgs = json.messages || [];
      const lines = msgs
        .slice(0, 50)
        .map(
          (m) =>
            `${m.ts} | user=${m.user || m.bot_id || '?'} | ${truncate(m.text || '(no text)', 200)}`,
        );
      process.stdout.write(`Success: ${msgs.length} message(s) in ${payload.channel}.\n${lines.join('\n')}\n`);
      if (json.response_metadata && json.response_metadata.next_cursor) {
        process.stdout.write(`next_cursor=${json.response_metadata.next_cursor}\n`);
      }
      break;
    }
    case 'create-channel':
      process.stdout.write(
        `Success: ${json.is_private ? 'Private' : 'Public'} channel created: ${json.channel.name} (id=${json.channel.id}).\n`,
      );
      break;
    case 'invite':
      process.stdout.write(
        `Success: Invited ${payload.users} to channel ${json.channel ? json.channel.id : payload.channel}.\n`,
      );
      break;
    case 'users': {
      const users = json.members || [];
      const lines = users
        .slice(0, 50)
        .map((u) => `${u.id} | ${u.name} | ${u.real_name || ''} | ${u.deleted ? 'deleted' : 'active'}`);
      process.stdout.write(`Success: ${users.length} user(s).\n${lines.join('\n')}\n`);
      if (json.response_metadata && json.response_metadata.next_cursor) {
        process.stdout.write(`next_cursor=${json.response_metadata.next_cursor}\n`);
      }
      break;
    }
    case 'user-by-email': {
      const u = json.user || {};
      process.stdout.write(
        `Success: ${u.name} (id=${u.id}, real_name=${u.real_name || ''}, tz=${u.tz || ''}).\n`,
      );
      break;
    }
  }
}

main();
